import {workspaceArtwork,productArtwork,personalArtwork,familiarPortrait} from './visuals.js';
import {uiIcon} from './icons.js';
import {CAREER_ART,growthPages,relationshipArtwork} from './album.js';
import {memoryTitle} from './memory-titles.js';
import {weekday,isWeekend,canWorkToday,weekendExplanation} from './calendar.js';
import {PEOPLE, PRODUCTS, TACTICS, FACTORIES, SHIPMENTS} from './content.js';
import {createGame,reduce,offers,offerPreview,quote,reputation,shipmentNote,canStart,canDate,chapter,hasEnding,parseSave,chatScene,nextStory,canCommit,canFinish,finaleGoal,dateScene,nextWorkStory,workScene,personUnlocked,recentDeliveryForInquiry} from './engine.js';
import {STORY_EVENTS,storyEvent,FINALES,RELATIONSHIP_ENDINGS} from './story.js';
import {WORK_STORIES} from './relationships.js';
import {negotiationOptions} from './negotiation.js';
import {soundEnabled,setSoundEnabled,playSound} from './sound.js';
import {careerEpilogue} from './epilogue.js';
const SOUND_KEY='trade-tycoon:sound';try{setSoundEnabled(localStorage.getItem(SOUND_KEY)==='on');}catch{}
const KEY='trade-tycoon:v1';const app=document.querySelector('#app');const dialog=document.querySelector('#dialog');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>'¥'+v.toLocaleString('zh-CN');let state=null,tab='desk',personFilter='all',memoryFilter='all',startGender='female',notice='',noticeType='success',newPortraitId=null,newArtworkId=null,saveWarning='',timer,importRequest=0;
try{const raw=localStorage.getItem(KEY);if(raw)state=parseSave(raw);}catch{saveWarning='旧存档无法读取，尚未覆盖。可以先导出备份，或重新开始。';}
const icon=name=>uiIcon(name);
function portraitArtwork(id){return {xia:'lin-zhixia-v1.webp',zhou:'zhou-yu-v1.webp',tang:'tang-che-v1.webp',shen:'shen-zhaowan-v1.webp',lu:'lu-yanzhou-v1.webp',xu:'expansion/xu-qingchuan-v1.webp',gu:'expansion/gu-yuning-v1.webp',cheng:'expansion/cheng-jianshan-v1.webp'}[id];}
function portrait(p,size='',familiar=false){
 const artwork=(familiar?familiarPortrait(state,p.id):null)||portraitArtwork(p.id);if(artwork)return `<span class="portrait illustrated ${size}" aria-hidden="true"><img src="assets/art/${artwork}" alt="" loading="lazy"></span>`;
 const female=p.gender==='female';return `<span class="portrait ${size}" style="--portrait:${p.color||'#688e99'}" aria-hidden="true"><svg viewBox="0 0 100 118"><path d="M0 118V94Q14 73 50 76Q88 75 100 98v20" fill="${female?'#f1e7db':'#ebe6dc'}"/><path d="${female?'M24 57Q16 10 49 9Q86 9 77 63L82 88H19z':'M24 45Q16 10 49 9Q86 9 77 48L73 40H27z'}" fill="#394342"/><path d="M43 64h14v21H43" fill="#d9ac8b"/><ellipse cx="50" cy="44" rx="23" ry="29" fill="#f1ceb0"/><path d="M26 37Q20 6 50 9Q80 9 76 39L64 27Q44 39 30 24z" fill="#394342"/><path d="M36 46h5m18 0h5" stroke="#46403b" stroke-width="2" stroke-linecap="round"/><path d="M45 59q5 4 10 0" fill="none" stroke="#b17b69" stroke-width="1.5" stroke-linecap="round"/><path d="M28 83l22 17 23-17M50 100v18" fill="none" stroke="${female?'#ba9480':'#809b98'}" stroke-width="2"/>${!female?'<path d="M21 66l5-28 4 23v10zM74 34l5 31-7 5V47z" fill="#394342"/>':''}</svg></span>`;
}
function productPicture(id){const artwork=productArtwork(id);return artwork?`<span class="product-icon illustrated-product" aria-hidden="true"><img src="assets/art/${artwork}" alt="" loading="lazy"></span>`:'';}
function workspacePicture(){const art=workspaceArtwork(state);return artworkPanel(art.art,art.title,'workspace-art');}
function personalPicture(){const art=personalArtwork(state);return art?artworkPanel(art.art,art.title,'life-art'):'';}
function scene(){return `<div class="harbor" aria-hidden="true"><span class="sun"></span><span class="island"></span><div class="crane one"></div><div class="crane two"></div><div class="containers"><i></i><i></i><i></i><i></i><i></i></div><div class="ship"><span></span></div><div class="sea-line a"></div><div class="sea-line b"></div><div class="sea-line c"></div><span class="harbor-caption">每一笔小生意，都通向更远的地方。</span></div>`;}
function button(label,action,id='',cls='button',disabled=false,description=''){return `<button class="${cls}" data-action="${action}" ${id?`data-id="${esc(id)}"`:''} ${description?`aria-describedby="${esc(description)}"`:''} ${disabled?'disabled':''}>${label}</button>`;}
function toast(text){clearTimeout(timer);const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');timer=setTimeout(()=>el.classList.remove('show'),4000);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));saveWarning='';}catch{saveWarning='浏览器无法保存。请在手账中导出存档，避免关闭后丢失。';}}
function act(action){const result=reduce(state,action);newArtworkId=result.changed&&action.type==='date'&&!relationshipArtwork(state,action.id)&&relationshipArtwork(result.state,action.id)?action.id:null;newPortraitId=result.changed&&action.type==='chat'&&!familiarPortrait(state,action.id)&&familiarPortrait(result.state,action.id)?action.id:null;if(tab==='people'&&['chat','date','recruit','boundary','commit'].includes(action.type)&&personUnlocked(state,action.id))personFilter=action.id;if(result.changed){state=result.state;save();playSound(({ship:'order',story:'story','work-story':'story',date:'date',commit:'ending',rest:'morning',evening:'evening'})[action.type]||'tap');}notice=result.message;noticeType=result.kind;render();const current=tab==='desk'?(state.active?document.querySelector('.order-panel'):action.type==='ship'?document.querySelector('.delivery-card'):null):null;if(current)current.scrollIntoView({block:'start',behavior:'instant'});else window.scrollTo({top:0,behavior:'instant'});if(!result.changed)toast(result.message);if(result.changed&&action.type==='commit')relationshipMoment(action.id);}
function newPortraitFeedback(){const p=PEOPLE.find(p=>p.id===newPortraitId);return p?`<span class="portrait-unlock"><strong>新的立绘 · 熟悉后的笑意</strong><small>三次普通相处留下的变化，不需要约会。</small>${button(`看看${p.name}的新表情 →`,'portrait-view',p.id,'text-button')}</span>`:'';}
function newArtworkFeedback(){const p=PEOPLE.find(p=>p.id===newArtworkId);return p&&relationshipArtwork(state,p.id)?`<span class="portrait-unlock"><strong>新的回忆插画已保存</strong><small>这一晚留下的画面，可以随时回看，不消耗时间。</small>${button(`看看与${p.name}的回忆插画 →`,'memory-art',p.id,'text-button')}</span>`:'';}
function feedback(extra=''){return `<div class="notice ${noticeType} ${extra}" role="status"><span>${noticeType==='warning'?'!':'✦'}</span><p>${newPortraitFeedback()}${newArtworkFeedback()}${esc(notice)}</p><button data-action="dismiss" aria-label="关闭消息">×</button></div>`;}
function dismissDialog(){dialog.onclose=null;dialog.onsubmit=null;if(dialog.open)dialog.close('cancel');}
function openDialog(onChoice,alreadyOpen=false){
 dialog.onsubmit=null;
 const openedState=state;
 dialog.onclose=()=>{const value=dialog.returnValue;dialog.onclose=null;if(state!==openedState){toast('进度已变化，请重新打开这段对话。');return;}onChoice(value);};
 dialog.returnValue='';if(!alreadyOpen)dialog.showModal();
}
function modal(title,html,onConfirm,label='确认',danger=false,cancelLabel='再想想'){
 dialog.innerHTML=`<form method="dialog"><div class="modal-top"><span class="eyebrow">由你决定</span><button value="cancel" class="close" aria-label="关闭">×</button></div><h2 id="dialog-title">${esc(title)}</h2><div class="modal-copy">${html}</div><div class="modal-actions"><button value="cancel" class="button secondary">${esc(cancelLabel)}</button><button value="confirm" class="button ${danger?'danger':''}" id="confirm-action">${esc(label)}</button></div></form>`;
 openDialog(value=>{if(value==='confirm')onConfirm();});
}
function conversation(id){
 const p=PEOPLE.find(p=>p.id===id),scene=chatScene(state,id);if(!p||!scene)return;
 dialog.innerHTML=`<form method="dialog"><div class="modal-top"><span class="eyebrow">${isWeekend(state)?'周末':'下班'} · 一段相处时光</span><button value="cancel" class="close" aria-label="关闭">×</button></div><div class="conversation-speaker">${portrait(p)}<div><small class="muted">${p.role}</small><h2 id="dialog-title">${p.name}</h2></div></div><p class="conversation-scene">${esc(scene.scene)}</p><span class="field-label">你想怎么回应？</span><div class="conversation-choices">${scene.choices.map((c,i)=>`<button value="reply-${i}" class="choice"><span>${esc(c.line)}</span><span>→</span></button>`).join('')}</div><button value="cancel" class="text-button small">今晚先不聊，改天再说</button></form>`;
 openDialog(chosen=>{if(chosen==='reply-0'||chosen==='reply-1')act({type:'chat',id,response:Number(chosen.slice(-1))});});
}
function viewPortrait(id,variant=null){
 if(variant===null)variant=familiarPortrait(state,id)?'familiar':'base';
 const p=PEOPLE.find(person=>person.id===id),familiar=familiarPortrait(state,id),artwork=variant==='familiar'&&familiar?familiar:portraitArtwork(id);if(!p||!artwork||!personUnlocked(state,id))return;
 dialog.innerHTML=`<form method="dialog"><div class="modal-top"><span class="eyebrow">角色立绘 · 已相识</span><button value="cancel" class="close" aria-label="关闭">×</button></div><h2 id="dialog-title">${esc(p.name)}</h2><p class="muted">${esc(p.role)} · ${p.age} 岁</p>${familiar?`<div class="portrait-variants" role="group" aria-label="立绘版本"><button value="base" class="button secondary" aria-pressed="${variant!=='familiar'}">初识印象</button><button value="familiar" class="button secondary" aria-pressed="${variant==='familiar'}">熟悉后的笑意</button></div><small class="muted">相处三次后留下的熟悉感，不需要约会。</small>`:''}<figure class="portrait-view"><img src="assets/art/${artwork}" alt="${esc(p.name)}的角色立绘"></figure><p class="portrait-caption">${esc(p.tag)}</p><button value="cancel" class="button secondary full">回到人物</button></form>`;
 openDialog(value=>{if(value==='base'||value==='familiar')viewPortrait(id,value);});
}
function renderStart(){
 app.innerHTML=`<main class="welcome"><div class="welcome-art"><div class="wordmark light"><img src="assets/mark.svg" alt="">外贸达人养成记<span>TRADE TYCOON</span></div><div class="welcome-title"><span class="eyebrow">一间小公司，一段大人生</span><h1>向海而生<br>由你掌舵。</h1><p>从第一封询盘开始，<br>把生意做成自己的样子。</p></div>${scene()}</div><section class="welcome-form"><span class="eyebrow">你的故事，从这里开始</span><h2>你好，新同事。</h2><p class="muted">上午认真谈一笔生意，晚上留一盏灯给生活。<br>成长与恋爱，都有你自己的节奏。</p>${saveWarning?`<p class="warning">${esc(saveWarning)}</p>${button('导出原存档','export','','text-button')}`:''}<form id="start-form"><label class="field-label" for="player-name">怎么称呼你</label><input id="player-name" name="name" maxlength="12" value="小满" autocomplete="off" required><span class="field-label">选择主角</span><div class="gender-options">${['female','male'].map(g=>`<button type="button" class="gender-choice ${g===startGender?'selected':''}" data-action="gender" data-id="${g}" aria-pressed="${g===startGender}">${portrait({gender:g,color:g==='female'?'#b97857':'#688e99'})}<span>${g==='female'?'女主角':'男主角'}</span></button>`).join('')}</div><button class="button full start-button" type="submit">开始第一天 <span>↗</span></button></form><div class="welcome-import">${button('已有存档？导入继续','import','','text-button')}<input type="file" id="import-file" accept="application/json,.json" hidden></div><div class="welcome-points"><span>◌ 恋爱完全自愿</span><span>◌ 自动保存在当前浏览器</span></div></section></main>`;
 document.querySelector('#start-form').onsubmit=e=>{e.preventDefault();const name=new FormData(e.target).get('name');const start=()=>{state=createGame(name,startGender);personFilter='all';memoryFilter='all';newPortraitId=null;newArtworkId=null;save();notice='欢迎来到启航贸易。今天先选一笔询盘，试着听懂客户真正的需求。';render();};if(saveWarning)modal('重新开始？','<p>新游戏将替换当前浏览器里无法读取的旧存档。建议先导出备份。</p>',start,'开始新游戏',true);else start();};bindImport();
}
function revenueBreakdown(r){if(!r.revenueParts)return '';const labels={base:'询盘基价',negotiation:'谈判条款',sales:'销售协作',brand:'自有品牌',team:'团队流程',regional:'区域渠道'};return `<p class="receipt-breakdown">合同额构成：${Object.entries(labels).filter(([key])=>r.revenueParts[key]>0).map(([key,label])=>`${label} ${money(r.revenueParts[key])}`).join(' + ')} = ${money(r.revenue)}。</p>`;}
function deliveryCard(compact=false){
 const r=state.lastDelivery;if(!r)return '';const p=PRODUCTS.find(p=>p.id===r.product),points=r.points;const unlocked=!compact&&state.phase==='day'&&!state.active?nextStory(state):null;
 const factors=[['谈判方案',points.plan],['品质',points.quality],['提前交付',points.speed],['精品专长',points.boutique],['长期合作',points.independent]].filter(([,value])=>value!==0);
 return `<section class="panel delivery-card ${compact?'delivery-compact':''}" aria-label="最近订单结算" tabindex="-1"><div class="delivery-heading"><div><span class="eyebrow">第 ${r.day} 天 · 第 ${r.number} 笔交付</span><h3>${esc(r.story.title)}</h3><p>${esc(p.name)} · ${esc(r.buyer)} 的回信</p></div><span class="delivery-seal" aria-label="已结算">${uiIcon('check')}已结算</span></div><div class="delivery-totals"><div><small>${r.stage==='employee'?'你的提成':'本单净利润'}</small><strong>+${money(r.gain)}</strong></div><div><small>合作口碑</small><strong>+${points.total}<em>点</em></strong></div></div><p class="delivery-customer">“${esc(r.story.customer)}”</p><p class="delivery-team">${esc(r.story.team)}</p>${deliveryFollowup(r)}${r.story.milestone?`<aside class="delivery-growth" aria-label="交付成长记录"><span class="eyebrow">这一刻，值得记下</span><p>${esc(r.story.milestone)}</p></aside>`:''}<div class="delivery-factors" aria-label="口碑构成">${factors.map(([label,value])=>`<span class="${value<0?'factor-cost':''}">${label} ${value>0?'+':''}${value}</span>`).join('')}</div>${unlocked?`<div class="delivery-next"><small>新的故事已经开启 · 不消耗工作步骤</small>${button("继续故事："+unlocked.title+" →","story-open",unlocked.id,"text-button")}</div>`:!compact&&canFinish(state)?`<div class="delivery-next"><small>事业目标已经达成 · 可以继续经营</small>${button("写下事业终章 →","finale","","text-button")}</div>`:""}<details class="delivery-details"><summary>回看这笔生意的选择与回款</summary><p>${esc(r.planTitle)} → ${esc(FACTORIES.find(f=>f.id===r.factory).name)} → ${esc(SHIPMENTS.find(sh=>sh.id===r.shipment).name)}</p>${revenueBreakdown(r)}<p>合同额 ${money(r.revenue)} − 总成本 ${money(r.cost)} = 订单利润 ${money(r.profit)}。</p><p>${r.stage==='employee'?`公司承担采购资金，你领取订单利润的 30%：${money(r.gain)}。`:`返还垫资 ${money(r.reserve)} + 净利润 ${money(r.gain)}，本次回款使周转资金增加 ${money(r.reserve+r.gain)}。垫资返还不是额外利润。`}</p><small>这是交付时的记录。后续升级或招聘不会重算这一单。</small></details></section>`;
}
function pendingOrder(){const a=state.active;if(!a)return '';return `<aside class="pending-order" aria-label="保留中的订单"><span>${uiIcon('ship')}</span><div><strong>${esc(a.buyer)} · ${esc(a.name)}</strong><p>下一步：${{talk:'沟通需求与方案',factory:'选择工厂',ship:'安排出运与回款'}[a.step]}。进度已保存，白天再决定什么时候继续。</p>${a.reserve?`<small>垫资 ${money(a.reserve)} 仍在这笔订单中，不会因休息消失。</small>`:''}</div></aside>`;}
function desk(){
 if(state.phase==='evening')return `<section class="panel evening-panel"><span class="eyebrow">${isWeekend(state)?'周末，按自己的节奏':'把时间还给自己'}</span><h2>${isWeekend(state)?'晚风里，也可以不赶时间。':'下班之后，<br>不只有一种安排。'}</h2><p class="evening-budget">${state.eveningUsed?'今晚已经留下一段相处回忆。<br>可以回看故事，或直接回家休息。':'今晚还可以相处 1 次，聊天或约会都算。<br>也可以直接休息，不影响明天的生意。'}</p><div class="evening-orb">☾</div>${button(state.eveningUsed?'回看身边的人':'去看看身边的人','tab','people')}${button('今天想一个人休息 →','rest','','text-button')}</section>${pendingOrder()}${dailyRecap()}`;
 const a=state.active;
 if(isWeekend(state)&&!state.weekendWork)return `<section class="panel weekend-panel"><span class="eyebrow">${weekday(state)} · 双休日</span><h2>今天，可以慢一点。</h2><p>${weekendExplanation(state)}</p>${a?`<p class="muted">${esc(a.name)} 的进度和垫资会完整保留，不必为了周末清空订单。</p>`:''}<div class="weekend-life-choices"><span class="field-label">先给自己留一个慢慢过的白天</span>${button('去海边与街巷走走','weekend-time','walk','button secondary full')}${button('在家做点喜欢的小事','weekend-time','home','button secondary full')}<small class="muted">不花游戏币，不加数值，也不会用掉晚上的相处机会。</small></div><div class="weekend-actions">${button('直接安排今晚的休息与约会 →','evening','','button full')}${button(a?'我想自愿继续这笔交付':'看看可选的紧急订单','weekend-work','','button secondary full')}</div><small class="muted">没有强制出勤、休息惩罚或错过即消失的人物剧情。</small></section>${milestone()}`;
 return `${isWeekend(state)?'<p class="gentle-banner">这是你自愿安排的周末工作。随时可以结束，未完订单照常保留。</p>':''}${!a&&state.lastDelivery?.day===state.day?deliveryCard():''}<div class="section-heading"><div><span class="eyebrow">${a?'正在推进':isWeekend(state)?'自愿处理 · 紧急询盘':'今日询盘'}</span><h2>${a?'把这笔生意做好。':'世界，比想象中近。'}</h2></div><span class="pill">剩余 ${state.ap} 个工作步骤</span></div>${a?order(a):`<p class="section-intro">选一位客户，听懂需求。谈判、选厂、出运各用 1 个步骤。<br>收益范围已计入当前公司配置，具体金额取决于接下来选择的方案。今日推荐用于轮换了解客户需求，不代表收益最高。</p><div class="offer-grid">${offers(state).map(o=>{const done=state.usedOffers.includes(o.id),range=offerPreview(state,o.id);return `<article class="offer-card ${o.featured?'featured':''}"><div class="offer-top">${productPicture(o.product)}<span class="tag">${o.featured?'今日推荐':'新询盘'}</span></div><small class="muted">${esc(o.market)}</small><h3>${o.name}</h3><p class="buyer-request">“${o.request}”</p><div class="offer-finance"><span>合同基价<strong>${money(o.revenue)}</strong></span><span>${state.stage==='employee'?'方案提成范围':'方案利润范围'}<strong class="income-range">${money(range.min)}<wbr>–${money(range.max)}</strong></span></div>${button(done?'今日已处理':'打开询盘 ↗','accept',o.id,'button full',done||!state.ap)}</article>`;}).join('')}</div>`}${state.ap===0?`<div class="gentle-banner"><div><strong>今天的工作，先告一段落。</strong><p>未完成的订单明天仍然在。现在可以下班了。</p></div>${button('下班啦 →','evening')}</div>`:''}${state.stage==='founder'&&!state.active?`<div class="bridge-job"><span>需要更多周转金？老客户想请你核对一份五金规格。</span>${button('接代办工作 +¥350 · 1 步','bridge','','text-button',!state.ap)}</div>`:''}${workPanel()}${milestone()}`;
}
function priorDelivery(a){
 const r=recentDeliveryForInquiry(state,a);if(!r)return '';
 return `<details class="customer-recap prior-delivery"><summary>上次给这位客户交付同类产品时</summary><p>第 ${r.day} 天：${esc(r.planTitle)} → ${esc(FACTORIES.find(f=>f.id===r.factory).name)} → ${esc(SHIPMENTS.find(sh=>sh.id===r.shipment).name)}</p><p>当时${r.stage==='employee'?'提成':'净利润'} ${money(r.gain)}；${r.points.quality<0?'有轻微瑕疵，不能当成已经解决。':'按当时记录完成交付。'}</p><small>这里只保留最近一笔真实交付。本次需求和报价请重新确认，不自动沿用上次方案。</small></details>`;
}
function order(a){const q=quote(state);return `<section class="panel order-panel"><div class="order-head"><div class="order-title">${productPicture(a.product)}<div><span class="eyebrow">${esc(a.market)} / ${esc(a.buyer)}</span><h3>${esc(a.name)}</h3></div></div>${button('暂缓订单','cancel','','text-button')}</div><ol class="steps">${[['talk','谈判'],['factory','选厂'],['ship','出运与回款']].map(([key,name],i)=>`<li class="${a.step===key?'current':''} ${['talk','factory','ship'].indexOf(a.step)>i?'done':''}"><span>${i+1}</span>${name}</li>`).join('')}</ol>${a.step==='talk'?`<div class="customer-quote"><span class="quote-avatar">${esc(a.buyer[0])}</span><div><strong>${esc(a.buyer)}</strong><p>“${esc(a.request)}”</p></div></div>`:`<details class="customer-recap"><summary>${esc(a.buyer)} · 回看客户需求</summary><p>“${esc(a.request)}”</p></details>`}${a.step==='talk'?priorDelivery(a):''}${notice?feedback('inline-order-feedback'):''}${a.step==='talk'?`<h4>你准备怎么回应？</h4><div class="choice-list">${negotiationOptions(a).map(t=>`<button data-action="tactic" data-id="${t.id}" class="choice" ${!state.ap?'disabled':''}><span class="choice-symbol">↗</span><span><strong>${t.title}</strong><small>${t.detail}</small></span><span>→</span></button>`).join('')}</div>`:a.step==='factory'?`<h4>给承诺找一个可靠的落点</h4><div class="choice-list">${FACTORIES.map(f=>{const v=quote(state,f.id);return `<button class="choice" data-action="factory" data-id="${f.id}" ${!state.ap?'disabled':''}><span class="choice-symbol">⌂</span><span><strong>${f.name} <em>${f.label}</em></strong><small>${f.detail}</small>${factoryContext(f)?`<small class="factory-context">${factoryContext(f)}</small>`:''}<small class="numbers">${state.stage==='employee'?'公司承担垫资':`需垫资 ${money(v.reserve)}`} · 预计${state.stage==='employee'?'提成':'利润'} ${money(state.stage==='employee'?Math.floor(v.profit*.3):v.profit)}</small></span><span>→</span></button>`;}).join('')}</div>`:`<h4>最后一步，把好消息送到对岸</h4><div class="choice-list">${SHIPMENTS.map(sh=>{const v=quote(state,a.factory,sh.id),rp=reputation(state,sh.id);return `<button class="choice" data-action="ship" data-id="${sh.id}" ${!state.ap?'disabled':''}><span class="choice-symbol">≈</span><span><strong>${sh.name}</strong><small>${shipmentNote(state,sh.id)||sh.detail}</small><small class="numbers">本单${state.stage==='employee'?'提成':'净利润'} ${money(state.stage==='employee'?Math.floor(v.profit*.3):v.profit)} · 预计口碑 +${rp.total}${a.reserve?` · 垫资 ${money(a.reserve)} 一并返还`:''}</small></span><span>→</span></button>`;}).join('')}</div>`}<div class="order-foot">${state.stage==='employee'?'员工阶段：公司承担采购资金，你拿净利润的 30% 提成。':'创业阶段：客户先付 50% 定金，垫资是暂时占用，回款时返还。'}<br><span>游戏将海运、验货与收款压缩为步骤；所有金额统一为人民币游戏币。</span></div></section>`;}
function careerNextStep(){
 const s=state;if(s.story.finale)return '';
 const event=STORY_EVENTS.map(e=>storyEvent(s,e.id)).find(e=>e.stage===s.stage&&!s.story.decisions[e.id]&&(e.requires||[]).every(id=>s.story.decisions[id]));
 if(!event)return '';
 const remaining=Math.max(0,(s.stage==='employee'?(event.minCompleted||0)-s.completed:(event.minStartup||0)-s.startupOrders));
 const timing=remaining?`再完成 ${remaining} 笔${s.stage==='founder'?'创业':''}订单后开启。`:s.active?'故事条件已满足，先完成或暂缓在途订单。':s.phase!=='day'?'故事已开启，下个白天可以进入。':'故事已开启，现在可以进入。';
 return `<aside class="goal-story" aria-label="事业故事的下一步"><strong>下一段${s.stage==='employee'?'创业前':''}故事：${esc(event.title)}</strong><p>${timing}不消耗工作步骤，也不会因为休息错过。</p>${!remaining?button('进入这段事业故事 →','story-open',event.id,'text-button',!!s.active||s.phase!=='day'):''}${s.stage==='employee'?'<small>这两段是事业故事。聊天、约会和工作小插曲不计入此项。</small>':''}</aside>`;
}
function factoryContext(f){
 if(f.id!=='credit')return '';
 return state.stage==='employee'?'现在由公司垫资，账期不会增加你的收益，费用会降低提成；创业后可用于减少当期垫资。':'账期让 ¥600 货款延至回款时支付，但另有 ¥150 费用；减少当期垫资不等于额外利润。';
}
function deliveryFollowup(r){
 if(r.points.quality>=0&&r.points.plan!==1)return '';
 const defect=r.points.quality<0;
 return `<aside class="delivery-followup" aria-label="交付问题记录"><strong>${defect?'品质问题已记录 · 未记录修复':'客户顾虑仍留在记录里'}</strong><p>${defect?'本单已结算，瑕疵扣分已计入口碑。当前没有追加售后任务或隐含扣款，结算完成不代表瑕疵已解决。下笔可选验货或更稳妥的工厂。':'本单已结算，方案未完全回应客户需求，已体现在本单方案口碑。当前不会另加处理任务或扣款；下次报价仍需重新读需求。'}</p></aside>`;
}
function milestone(){
 const s=state;
 if(s.stage==='employee')return `<section class="milestone"><span class="eyebrow">下一站 · 带着准备出发</span><h3>一间属于自己的公司</h3><p>完成 3 笔订单、两个创业前故事，口碑达到 6，攒够 ¥5,000。支付 ¥3,000 启动费用，留下周转金再出发。</p><div class="goal-chips"><span>${s.completed>=3?'✓':'○'} 订单 ${Math.min(s.completed,3)}/3</span><span>${s.story.decisions.first_credit&&s.story.decisions.first_contract?'✓':'○'} 故事 ${Number(!!s.story.decisions.first_credit)+Number(!!s.story.decisions.first_contract)}/2</span><span>${s.rep>=6?'✓':'○'} 口碑 ${Math.min(s.rep,6)}/6</span><span>${s.cash>=5000?'✓':'○'} 积蓄 ${money(s.cash)}</span></div>${careerNextStep()}${button(canStart(s)?'准备好了，创立公司 ↗':'查看公司准备',canStart(s)?'startup':'tab',canStart(s)?'':'company','text-button')}</section>`;
 const g=finaleGoal(s),construction=s.staff.length>0||s.warehouse>1||s.logistics>0,storyCount=['direction','deadline','team','partnership','aftercare','legacy'].filter(id=>s.story.decisions[id]).length;
 return `<section class="milestone"><span class="eyebrow">${s.story.finale?'已抵达事业终章':'下一站 · '+(s.story.focus==='brand'?'自己的品牌':s.story.focus==='boutique'?'精品贸易公司':'决定公司的方向')}</span><h3>${s.story.finale?FINALES[s.story.finale].title:s.story.focus?g.title:'你希望它长成什么样？'}</h3><p>${s.story.finale?'可以继续经营、推进人物故事，或在手账里回看走过的选择。':!s.story.focus?'开门之后，先读一读新的故事，选择精品贸易或自有品牌方向。':s.story.focus==='brand'?'完成六个创业章节、10 笔创业订单，扩仓至 2 级并积累 ¥18,000，让自己的系列正式走向市场。':'完成六个创业章节与 8 笔创业订单，口碑达到 35，再完成一项公司建设。小公司也能有清楚的成功结局。'}</p>${s.story.focus?`<div class="goal-chips"><span>${s.startupOrders>=g.orders?'✓':'○'} 订单 ${Math.min(s.startupOrders,g.orders)}/${g.orders}</span><span>${storyCount===6?'✓':'○'} 创业故事 ${storyCount}/6</span>${g.rep?`<span>${s.rep>=g.rep?'✓':'○'} 口碑 ${Math.min(s.rep,g.rep)}/${g.rep}</span>`:''}${g.cash?`<span>${s.cash>=g.cash?'✓':'○'} 资金 ${money(s.cash)}</span><span>${s.warehouse>=2?'✓':'○'} 2 级仓库</span>`:`<span>${construction?'✓':'○'} 完成一项建设</span>`}</div>`:''}${careerNextStep()}${s.story.finale?button('回顾事业结局 →','finale-review','','text-button'):canFinish(s)?button('写下事业终章 ↗','finale','','text-button'):button('回到公司规划 →','tab','company','text-button')}</section>`;
}
function upcomingCareer(){
 const s=state;if(s.stage!=='founder'||s.story.finale||s.phase!=='day'||(isWeekend(s)&&!s.weekendWork))return '';
 const event=STORY_EVENTS.map(e=>storyEvent(s,e.id)).find(e=>e.stage==='founder'&&!s.story.decisions[e.id]&&(e.requires||[]).every(id=>s.story.decisions[id]));
 if(!event)return '';const remaining=Math.max(0,(event.minStartup||0)-s.startupOrders);if(!remaining)return '';
 const topic={deadline:'船期变化之后，怎样把承诺接住。',team:'团队流程或外部协作，会改变之后的订单。',partnership:'合作的范围与标准，由你重新商量。',aftercare:'货物签收以后，客户的使用反馈还会回来。',legacy:'上次售后留下的选择，会在这里带回结果。'}[event.id];
 if(!topic)return '';
 return `<aside class="story-next" aria-label="下一段事业故事"><span class="eyebrow">再完成 ${remaining} 笔创业订单 · 下一段故事</span><strong>${esc(event.title)}</strong><p>${esc(topic)}</p><small>按自己的节奏推进，不会因为休息错过。</small></aside>`;
}
function storyPanel(){if(state.active)return '';const e=nextStory(state);if(!e)return upcomingCareer();return `<section class="story-teaser"><div><span class="eyebrow">${e.kicker}</span><h3>${e.title}</h3><p>${esc(e.scene.split('\n')[0])}</p><small>${state.active?'完成手头订单后再聊这件事。':state.phase==='evening'?'下次白天，再按自己的节奏打开。':'不消耗工作步骤 · 选择会留下不同的结果'}</small></div>${button('进入故事 →','story-open',e.id,'button secondary',state.phase!=='day'||!!state.active)}</section>`;}
function openStory(id,review=false){
 const e=storyEvent(state,id);if(!e)return;const p=PEOPLE.find(p=>p.id===e.speaker),selected=e.choices.find(c=>c.id===state.story.decisions[id]);
 dialog.innerHTML=`<form method="dialog"><div class="modal-top"><span class="eyebrow">${e.kicker}</span><button value="cancel" class="close" aria-label="关闭">×</button></div><div class="conversation-speaker">${portrait(p)}<div><small class="muted">${p.name}</small><h2 id="dialog-title">${e.title}</h2></div></div>${!review?`<p class="story-reading-note">往下阅读后有 ${e.choices.length} 个选择。也可以点右上角关闭，稍后再继续。</p>`:''}${artworkPanel(CAREER_ART[e.stage==='employee'?'office':['aftercare','legacy'].includes(e.id)?'aftercare':state.story.focus||'boutique'],e.title)}<p class="conversation-scene">${esc(e.scene)}</p>${review?`<div class="story-review"><small>${state.story.memories?.[id]?`第 ${state.story.memories[id].day} 天 · 当时保存的这一页`:'旧版本未保存场景快照，以下为原章节与已记录的选择。'}</small><strong>你选择了：${esc(selected?.label||'')}</strong><p>${esc(selected?.outcome||'')}</p></div><button class="button full" value="cancel">回到手账</button>`:`<div class="conversation-choices">${e.choices.map(c=>`<button value="story:${c.id}" class="choice story-choice" ${state.cash+(c.effects.cash||0)<0?'disabled':''}><strong>${c.label}</strong><small>${c.detail}</small></button>`).join('')}</div><button value="cancel" class="text-button small">先留着，稍后再决定</button>`}</form>`;
 openDialog(value=>{if(!review&&value.startsWith('story:'))act({type:'story',id,choice:value.slice(6)});});
}
function showFinale(review=false){
 if(!review){const result=reduce(state,{type:'finale'});if(!result.changed){toast(result.message);return;}state=result.state;save();playSound('ending');render();}
 const ending=FINALES[state.story.finale];if(!ending)return;const echo=careerEpilogue(state);
 modal(ending.title,`${artworkPanel(CAREER_ART[state.story.finale],ending.title,'ending-art')}<div class="ending-stamp">向海贸易<small>事业终章 · ${state.story.finale==='brand'?'品牌之路':'精品之路'}</small></div><p class="finale-prose">${esc(ending.scene)}</p>${echo.decisions.length?`<details class="ending-reflections"><summary>看看这些选择，留下了什么</summary>${echo.decisions.map(item=>`<article><h3>${esc(item.title)}</h3><p>${esc(item.text)}</p></article>`).join('')}</details>`:''}${echo.workReflections.length?`<details class="ending-reflections"><summary>和伙伴留下的工作习惯</summary><small>以下是各自当时留下的回应，不代表加入公司或确认恋爱。</small>${echo.workReflections.map(item=>`<article><h3>${esc(item.person)} · ${esc(item.title)}</h3><small>第 ${item.day} 天的记录</small><p>你：“${esc(item.line)}”</p><p>${esc(item.text)}</p></article>`).join('')}</details>`:''}<section class="ending-life"><span class="eyebrow">现在的工作室 · 现在的生活</span><p>${esc(echo.workplace)}</p><p>${esc(echo.evening)}</p></section>`,()=>{},'继续书写之后的生活',false,'关闭');
}

function dateConversation(id){
 const p=PEOPLE.find(p=>p.id===id),scene=dateScene(state,id);if(!p||!scene)return;
 dialog.innerHTML=`<form method="dialog"><div class="modal-top"><span class="eyebrow">${isWeekend(state)?'周末':'下班'} · ${state.relations[id].status==='partner'?'恋人的日常':'自愿的约会'}</span><button value="cancel" class="close" aria-label="关闭">×</button></div><div class="conversation-speaker">${portrait(p)}<div><small class="muted">${p.role}</small><h2 id="dialog-title">与${p.name}的这一晚</h2></div></div><p class="date-intent">${state.relations[id].status==='partner'?'忙完之后，给彼此留一段时间。':'这是带有恋爱意向的相处。'}选择回应后才算一次约会；取消不会消耗今晚的时间。</p><p class="conversation-scene">${esc(scene.scene)}</p><span class="field-label">这一刻，你想怎么回应？</span><div class="conversation-choices">${scene.choices.map((c,i)=>`<button value="date-${i}" class="choice"><span>${esc(c.line)}</span><span>→</span></button>`).join('')}</div><button value="cancel" class="text-button small">今晚先不约，改天再说</button></form>`;
 openDialog(chosen=>{if(chosen==='date-0'||chosen==='date-1')act({type:'date',id,response:Number(chosen.slice(-1))});});
}
function workPanel(){const e=nextWorkStory(state);if(!e||state.phase!=='day'||isWeekend(state)||state.active||nextStory(state))return '';const p=PEOPLE.find(p=>p.id===e.person);return `<section class="work-moment"><div>${portrait(p)}<div><span class="eyebrow">工作日常 · ${p.name}</span><h3>${e.title}</h3><p>可选的小插曲，不消耗工作步骤，也不推进恋爱。</p></div></div>${button('停下来聊两句 →','work-story-open',e.id,'text-button')}</section>`;}
function openWorkStory(id,review=false){const record=state.workStories[id],scene=workScene(state,id,review?record?.setting:undefined);if(!scene||review&&!record)return;const p=PEOPLE.find(p=>p.id===scene.person),choice=scene.choices[record?.response];dialog.innerHTML=`<form method="dialog"><div class="modal-top"><span class="eyebrow">工作日常 · ${scene.setting==='office'?'身边的同事':'熟悉的朋友'}</span><button value="cancel" class="close" aria-label="关闭">×</button></div><div class="conversation-speaker">${portrait(p)}<div><small class="muted">${p.name}</small><h2 id="dialog-title">${scene.title}</h2></div></div><p class="conversation-scene">${esc(scene.scene)}</p>${review?`<div class="story-review"><strong>你：“${esc(choice.line)}”</strong><p>${esc(choice.reply)}</p></div><button value="cancel" class="button full">回到手账</button>`:`<div class="conversation-choices">${scene.choices.map((c,i)=>`<button value="work-${i}" class="choice"><span>${esc(c.line)}</span><span>→</span></button>`).join('')}</div><button value="cancel" class="text-button small">先忙手头的事</button>`}</form>`;openDialog(value=>{if(!review&&(value==='work-0'||value==='work-1'))act({type:'work-story',id,response:Number(value.slice(-1))});});}
function memoryArchive(){return `<section class="memory-archive panel"><span class="eyebrow">不只是订单上的名字</span><h3>人物回忆</h3><p class="muted">保留首次有记录的场景与当时的回应。回顾不消耗时间，也不会改变关系。</p><div class="people-shortcuts" role="group" aria-label="选择回忆中的人物">${['all',...PEOPLE.filter(p=>personUnlocked(state,p.id)).map(p=>p.id)].map(id=>`<button data-action="memory-person" data-id="${id}" aria-pressed="${memoryFilter===id}">${id==='all'?'所有人':PEOPLE.find(p=>p.id===id).name}</button>`).join('')}</div><div class="memory-people">${PEOPLE.filter(p=>personUnlocked(state,p.id)&&(memoryFilter==='all'||memoryFilter===p.id)).map(p=>{const r=state.relations[p.id],work=WORK_STORIES.filter(w=>w.person===p.id&&state.workStories[w.id]);return `<article class="memory-person"><div>${portrait(p)}<div><h4>${p.name}</h4><small>${Math.min(r.chats,3)} / 3 相处 · ${p.gender!==state.gender?`${Math.min(r.dates,3)} / 3 约会`:'朋友与同事'}</small></div></div><div class="memory-links">${Array.from({length:Math.min(r.chats,3)},(_,i)=>button(memoryTitle(p.id,'chat',i),'memory-review',`${p.id}:chat:${i}`,'text-button small')).join('')}${Array.from({length:Math.min(r.dates,3)},(_,i)=>button(memoryTitle(p.id,'date',i),'memory-review',`${p.id}:date:${i}`,'text-button small')).join('')}${relationshipArtwork(state,p.id)?button('查看这一幕的插画','memory-art',p.id,'text-button memory-art-link'):''}${hasCommitMemory(p.id)?button(r.status==='partner'?'把心意说清楚':'把心意说清楚（历史）','memory-review',`${p.id}:partner:0`,'text-button small'):''}${work.map(w=>button(w.title,'work-story-review',w.id,'text-button small')).join('')}${!r.chats&&!r.dates&&!work.length?'<small class="muted">还没有留下回忆，不必着急。</small>':''}</div></article>`;}).join('')}</div></section>`;}
function reviewMemory(key,scrollTop=0,alreadyOpen=false){
 const [id,kind,num]=key.split(':'),p=PEOPLE.find(p=>p.id===id),r=state.relations[id],i=Number(num);if(!p||!r)return;
 let scene,title,extra='';const memory=state.dialogueMemories[id];
 if(kind==='partner'&&hasCommitMemory(id)){relationshipMoment(id);return;}
 else if(['chat','date'].includes(kind)&&Number.isInteger(i)&&i>=0&&i<Math.min(r[kind==='chat'?'chats':'dates'],3)){
  const record=memory[kind][i];title=memoryTitle(id,kind,i);scene=record?.scene||p[kind==='chat'?'chats':'dates'][i];
  extra=record?`<div class="story-review"><small>第 ${record.day} 天 · 首次保存的这一幕${record.branch?' · 回应了更早的选择':''}</small><strong>你：“${esc(record.line)}”</strong><p>${esc(record.reply)}</p></div>`:'<p class="muted">旧版没有保存这一次的具体回应。这里保留场景原文，不替你补写选择。</p>';
 }else return;
 const art=kind==='date'&&i===2?relationshipArtwork(state,id):null;
 dialog.innerHTML=`<form method="dialog" data-reading-position="${scrollTop}"><div class="modal-top"><span class="eyebrow">当时留下的故事 · 只读回看</span><button value="cancel" class="close" aria-label="关闭">×</button></div><h2 id="dialog-title">${esc(p.name)} · ${esc(title)}</h2><div class="modal-copy">${art?`${artworkPanel(art,`${p.name} · ${title} · 当时的回忆`,'relationship-art')}<button value="art" class="button secondary full">查看插画大图</button>`:''}<p class="conversation-scene">${esc(scene)}</p>${extra}</div><div class="modal-actions"><button value="cancel" class="button secondary">关闭</button><button value="confirm" class="button">${tab==='people'?'回到人物':'回到手账'}</button></div></form>`;
 openDialog(()=>{},alreadyOpen);
 // Read-only image/text transitions keep the same dialog open. Native close
 // restores focus and scroll after its callbacks, so reopening there loses place.
 dialog.onsubmit=e=>{if(e.submitter?.value==='art'&&art){e.preventDefault();viewRelationshipArt(id,{key,scrollTop:dialog.scrollTop||0},false,true);}};
 if(alreadyOpen)dialog.querySelector?.('button[value="art"]')?.focus({preventScroll:true});dialog.scrollTop=scrollTop;
}
function viewRelationshipArt(id,returnTo=null,zoom=false,alreadyOpen=false){
 const p=PEOPLE.find(person=>person.id===id),artwork=relationshipArtwork(state,id);if(!p||!artwork||!personUnlocked(state,id))return;
 const title=memoryTitle(id,'date',2);
 dialog.innerHTML=`<form method="dialog" class="memory-art-viewer" data-reading-position="${returnTo?.scrollTop||0}"><div class="modal-top"><span class="eyebrow">已保存的插画 · 不消耗时间</span><button value="cancel" class="close" aria-label="关闭">×</button></div><h2 id="dialog-title">${esc(p.name)} · ${esc(title)}</h2><div class="portrait-variants" role="group" aria-label="插画大小"><button value="fit" class="button secondary" aria-pressed="${!zoom}">完整画面</button><button value="zoom" class="button secondary" aria-pressed="${zoom}">放大细节</button></div><p class="portrait-caption">${zoom?'可在图内横向和上下滚动，查看人物与物件。':'保留完整构图。想细看时，选择“放大细节”。'}</p><figure class="art-zoom-viewport ${zoom?'is-zoomed':''}" tabindex="0" aria-label="${zoom?'可滚动的插画细节':'完整插画'}"><img src="assets/art/${artwork}" alt="${esc(p.name)} · ${esc(title)} · 当时的回忆"></figure><button value="back" class="button secondary full">${returnTo?'回到原文':tab==='people'?'回到人物':'回到手账'}</button></form>`;
 openDialog(()=>{},alreadyOpen);
 dialog.onsubmit=e=>{const value=e.submitter?.value;if(value==='fit'||value==='zoom'){e.preventDefault();viewRelationshipArt(id,returnTo,value==='zoom',true);}else if(value==='back'&&returnTo){e.preventDefault();reviewMemory(returnTo.key,returnTo.scrollTop,true);}};
 if(alreadyOpen)dialog.querySelector?.(`button[value="${zoom?'zoom':'fit'}"]`)?.focus({preventScroll:true});dialog.scrollTop=0;
 // Start detail view at the middle of the illustration instead of the far-left
 // background. CSS provides its width even before image decode completes.
 if(zoom){const viewport=dialog.querySelector?.('.art-zoom-viewport');if(viewport)viewport.scrollLeft=Math.max(0,(viewport.scrollWidth-viewport.clientWidth)/2);}
}

function artworkPanel(artwork,title,extra=''){return `<figure class="chapter-art ${extra}"><img src="assets/art/${artwork}" alt="${esc(title)}" loading="lazy"></figure>`;}
function growthAlbum(){const pages=growthPages(state);if(!pages.length)return '';return `<section class="growth-album panel"><span class="eyebrow">一路走来的光</span><h3>把这一页，留在这里。</h3><p class="muted">已经完成的选择，变成可以回看的篇章。图画描绘故事意境，不是客户资料。</p><div class="growth-grid">${pages.map(p=>`<article>${artworkPanel(p.art,p.title)}<div><small>${p.kicker}</small><h4>${p.title}</h4><p>${p.text}</p></div></article>`).join('')}</div></section>`;}
function hasCommitMemory(id){const m=state.dialogueMemories[id];return !!m&&(state.relations[id]?.status==='partner'||!!m.commitmentRecord||!!m.commitment);}
function relationshipMoment(id){const p=PEOPLE.find(p=>p.id===id),r=state.relations[id];if(!p||!hasCommitMemory(id))return;const memory=state.dialogueMemories[id],historical=r.status!=='partner',record=memory.commitmentRecord,scene=record?.scene||(historical?'':RELATIONSHIP_ENDINGS[id]),echo=record?.echo||memory.commitment;modal(`与${p.name} · 把心意说清楚`, `<div class="relationship-keepsake">${portrait(p)}<span class="eyebrow">${record?`第 ${record.day} 天 · 当时保存的这一页`:'不是任务奖励，是彼此的选择'}</span><h3>${historical?'曾经说清的心意，<br>也可以好好留着。':'往后的普通日子，<br>也想和你分享。'}</h3><span class="tag">${historical?'历史回忆 · 当前不处于正式关系':'正式交往 · 工作与生活仍各自完整'}</span></div>${scene?`<p class="conversation-scene">${esc(scene)}</p>`:''}${echo?`<p class="commitment-echo">${esc(echo)}</p>`:''}<small class="muted">${historical?'这是当时的记录。回看不会恢复恋爱关系，也不会改变你现在的选择。':'这段回忆已放进手账，可以随时回来读。'}${historical&&!record?'旧版没有保存完整确认场景，这里只保留当时记录的约定。':''}</small>`,()=>{},historical?'回到手账':'收好这一晚',false,'关闭');}

function dailyRecap(){const today=state.logs.filter(l=>l.day===state.day).slice(0,2);return `<section class="panel small-panel"><span class="eyebrow">今日一页</span><h3>努力，也有回声。</h3>${personalPicture()}${today.length?today.map(l=>`<div class="recap"><strong>${esc(l.title)}</strong><p>${esc(l.text)}</p></div>`).join(''):'<p class="muted">今天可以不留下些什么。好好休息，明天再继续也很好。</p>'}</section>`;}
function recruitHint(p){
 if(state.staff.includes(p.id))return '已加入团队。合作与恋爱始终分开。';
 const timing=state.phase!=='day'?'白天再聊工作邀请。':state.active?'先完成在途订单，再确认入职。':'是否接受，由对方决定。';
 if(!p.recruit)return '对方有自己的工作安排，不以恋爱交换合作。'+timing;
 const ready=state.startupOrders>=2&&state.relations[p.id].trust>=3;
 return (ready?'订单与相处条件已满足。':'先完成 2 笔创业订单、相处 3 次。')+'入职 ¥1,200，每日工资 ¥80；不需要恋爱。'+timing;
}
function personCardIntro(p){
 const r=state.relations[p.id],memory=state.dialogueMemories[p.id];
 const kind=r.dates?'date':'chat',count=r.dates||r.chats,index=Math.min(count,3)-1,record=memory?.[kind]?.[index];
 if(!record)return `<p class="person-intro">${p.intro.replaceAll('\n','<br>')}</p>`;
 return `<div class="person-current"><small>${r.status==='partner'?'已经认真确认过心意':'你们已经留下的故事'} · ${esc(memoryTitle(p.id,kind,index))}</small><p>你：“${esc(record.line)}”</p><p class="muted">${esc(record.reply)}</p><div class="person-memory-links">${button('回看这一幕','memory-review',`${p.id}:${kind}:${index}`,'text-button')}${button('与 TA 的回忆','memory-person',p.id,'text-button')}</div></div><details class="person-original"><summary>初识时的印象</summary><p>${esc(p.intro)}</p></details>`;
}
function dateHint(p){
 const r=state.relations[p.id];
 if(r.status==='closed')return '现在保持朋友关系。是否重新了解彼此，由你决定。';
 if(p.manager&&state.stage==='employee')return '在职期间保持职业边界，不能提出约会。';
 if(PEOPLE.some(other=>other.id!==p.id&&state.relations[other.id].status==='partner'))return '你已有正式关系，暂不向其他人发起约会。';
 if(r.trust<2)return '先聊过 2 次，再考虑约会。';
 if(state.phase!=='evening')return '相处条件已满足，今晚可以选择约会，也可以只聊近况。';
 if(state.eveningUsed)return '今晚的相处机会已用完，明晚可以选择约会。不急，也可以休息。';
 return '今晚可以选择约会，也可以只聊近况或休息。';
}
function people(){return `<div class="section-heading"><div><span class="eyebrow">同行的人</span><h2>一起工作，也一起生活。</h2></div></div><p class="section-intro">所有角色均为成年人。工作合作与恋爱分开，拒绝或结束关系不会减少收益。${state.phase==='day'?'下班后，可以选择一段相处时光。':state.eveningUsed?'今晚已经留下一段回忆，可以休息了。':'今晚可相处 1 次，聊天或约会都算。其他人明天再聊，也可以直接休息。'}</p><div class="people-shortcuts" role="group" aria-label="选择想见的人"><button data-action="person-select" data-id="all" aria-pressed="${personFilter==='all'}">所有人</button>${PEOPLE.filter(p=>personUnlocked(state,p.id)).map(p=>`<button data-action="person-select" data-id="${p.id}" aria-pressed="${personFilter===p.id}">${p.name}</button>`).join('')}</div><div class="people-grid">${PEOPLE.filter(p=>personUnlocked(state,p.id)&&(personFilter==='all'||p.id===personFilter)).map(p=>{const r=state.relations[p.id];const same=p.gender===state.gender;const locked=p.manager&&state.stage==='employee';return `<article class="person-card"><div class="person-header">${`<button class="portrait-button" data-action="portrait-view" data-id="${p.id}" aria-label="查看${p.name}的角色立绘" aria-haspopup="dialog">${portrait(p,'',true)}<small class="portrait-view-hint">${familiarPortrait(state,p.id)?'2 版立绘 · 已解锁':'查看立绘'}</small></button>`}<div><small class="muted">${p.role} · ${p.age} 岁</small><h3>${p.name}</h3><span class="tag">${state.staff.includes(p.id)?'你的团队':r.status==='partner'?'恋人':r.status==='dating'?'约会中':r.status==='closed'?'保持朋友关系':r.trust>=3?'彼此熟悉':'正在认识'}</span></div></div><h4>${p.tag}</h4>${personCardIntro(p)}<div class="relationship"><span>相处 ${r.chats} 次</span><span>${r.dates?`约会 ${r.dates} 次`:same?'伙伴与朋友':locked?'在职期间保持职业边界':'感情由你选择'}</span></div><div class="person-actions">${button('聊聊近况','chat',p.id,'button secondary',state.phase!=='evening'||state.eveningUsed)}${!same?button(['dating','partner'].includes(r.status)?'再约一次':'提出约会','date',p.id,'button',state.phase!=='evening'||state.eveningUsed||!canDate(state,p.id),`date-hint-${p.id}`):''}</div>${!same?`<p class="date-hint" id="date-hint-${p.id}">${esc(dateHint(p))}</p>`:''}${!same&&r.status==='dating'&&r.dates>=3?`<div class="commit-row">${button('认真谈谈我们的关系','commit',p.id,'button secondary full',state.phase!=='evening'||state.eveningUsed||!canCommit(state,p.id))}<small>${r.trust>=3?(state.phase==='day'?'心意已准备好，今晚可以认真谈谈。':state.eveningUsed?'心意已准备好，明晚可以认真谈谈。':'如果你愿意，现在可以认真谈谈。'):'先相处 3 次、约会 3 次。'}事业和工作不受关系选择影响。</small></div>`:''}${!same?`<div class="person-note">${r.status==='closed'?button('我想重新了解彼此','reopen',p.id,'text-button small'):button(r.status==='partner'?'结束关系，保留友谊':r.status==='dating'?'停止约会，保留友谊':'只做朋友','boundary',p.id,'text-button small')}</div>`:''}${state.stage==='founder'?`<div class="recruit-row">${button(state.staff.includes(p.id)?'已加入团队':'聊聊加入工作室','recruit',p.id,'text-button small',state.staff.includes(p.id)||state.phase!=='day'||!!state.active)}<small>${recruitHint(p)}</small></div>`:''}</article>`;}).join('')}</div>`;}
function upgradeHint(cost,done){if(done)return '';const reason=state.active?'先完成或暂缓在途订单，再安排建设。':state.phase!=='day'?'今晚先把时间留给生活，白天有空时再安排建设，不要求接单。':state.cash<cost?`还差 ${money(cost-state.cash)} 周转资金；可以先经营或接代办工作。`:'';return reason?`<small class="upgrade-hint">${reason}</small>`:'';}
function company(){return `<div class="section-heading"><div><span class="eyebrow">${state.stage==='employee'?'你的下一步':'向海贸易 / XIANGHAI'}</span><h2>${state.stage==='employee'?'认真工作，也保留自己的方向。':'公司不必很大，梦想可以。'}</h2></div></div><section class="company-hero">${workspacePicture()}<div><span class="eyebrow">${state.stage==='employee'?'从业务员到创始人':'新航线正在展开'}</span><h3>${state.stage==='employee'?'准备一场有底气的出发。':'这一次，你来决定方向。'}</h3><p>${state.stage==='employee'?'先积累本事、口碑和周转金。创业不要求与任何人恋爱，也不要求接受投资。':'不填复杂表格。仓库决定订单规模，物流优化每单成本，同事负责自己的专长。'}</p>${state.stage==='employee'?button('完成交接，创立公司','startup','','button',!canStart(state)):button('回到工作台 →','tab','desk','button secondary')}</div></section>${state.stage==='employee'?milestone():`${state.story.focus?`<div class="direction-summary"><strong>${state.story.focus==='brand'?'自有品牌路线':'精品贸易路线'}</strong><span>${state.story.focus==='brand'?'品牌每单溢价 +¥700，包装成本 +¥300。':'品质需求谈妥的订单额外 +1 口碑。'}${state.story.operations==='network'?' 外包协作每单降低 ¥100 成本。':state.story.operations==='team'?' 团队流程让每位员工每单额外创造 ¥120 合同额。':''}</span></div>`:''}<div class="upgrade-grid"><section class="panel"><span class="building-icon">${uiIcon('warehouse')}</span><h3>小而有序的仓库</h3><p>${state.warehouse===1?'一排货架，先把每件事做好。':'两排货架，承接更大规模的询盘。'}</p><small>扩仓后，合同基价 +¥1,800，采购成本 +¥1,000。</small>${button(state.warehouse===2?'已扩建至 2 级':'扩建货架 · ¥1,400','warehouse','','button full',state.warehouse===2||state.cash<1400||!!state.active||state.phase!=='day')}${upgradeHint(1400,state.warehouse===2)}</section><section class="panel"><span class="building-icon">${uiIcon('ship')}</span><h3>熟悉的物流伙伴</h3><p>${state.logistics?'固定拼箱合作已经建立。':'不必自己开一家船公司，找一个稳定的伙伴。'}</p><small>一次建立合作，每笔订单物流成本减少 ¥100。</small>${button(state.logistics?'已建立固定合作':'建立合作 · ¥1,000','logistics','','button full',!!state.logistics||state.cash<1000||!!state.active||state.phase!=='day')}${upgradeHint(1000,!!state.logistics)}</section><section class="panel"><span class="building-icon">${uiIcon('people')}</span><h3>一起把事情做好</h3><p>${state.staff.length?state.staff.map(id=>PEOPLE.find(p=>p.id===id).name).join('、')+'，已加入你的团队。':'熟悉的人可以成为同事，也可以继续做朋友。'}</p><small>入职安排 ¥1,200 / 人，每日工资 ¥80。对方可以拒绝。</small>${button('去聊聊工作机会 →','tab','people','button secondary full')}</section></div>${milestone()}`}`;}
function journal(){return `<div class="section-heading"><div><span class="eyebrow">生活与生意的回声</span><h2>每一步，都算数。</h2></div><span class="pill">最近 50 条</span></div><section class="save-tools panel"><div><strong>你的进度，只在这个浏览器里。</strong><p>换设备前请导出存档。不上传个人信息，也不连接真实支付。</p></div><div>${button('导出存档','export','','button secondary')}${button('导入存档','import','','button secondary')}${button('重新开始','reset','','text-button')}</div><input type="file" id="import-file" accept="application/json,.json" hidden></section><div class="journal-jumps">${button('直达人物回忆 →','memory-person',memoryFilter,'text-button')}</div>${deliveryCard(true)}${growthAlbum()}${memoryArchive()}${Object.keys(state.story.decisions).length?`<section class="story-archive panel"><span class="eyebrow">那些改变方向的选择</span><h3>故事回顾</h3><div>${STORY_EVENTS.filter(e=>state.story.decisions[e.id]).map(e=>button(e.title+' →','story-review',e.id,'text-button')).join('')}</div></section>`:''}<div class="timeline">${state.logs.map(l=>`<article><span class="timeline-day">DAY ${String(l.day).padStart(2,'0')}</span><h3>${esc(l.title)}</h3><p>${esc(l.text)}</p></article>`).join('')}</div><div class="prototype-note">完整版 v1.0.1 · 共 3 种五金产品、9 组轮换询盘、8 个经营章节、2 个事业结局与 8 位成年角色关系线。新增三位在不同事业阶段相识的朋友，聊天与约会有双回应和第三幕回响；共有 ${WORK_STORIES.length} 段工作日常、双休日选择和具名人物回忆。进度保存在当前浏览器，换设备前请导出备份。本作不连接真实支付。<br>制作说明：本作使用 AI 辅助制作，插画由 OpenAI 图像生成工具制作。角色与故事均为虚构。</div>`;}
function bindImport(){const file=document.querySelector('#import-file');if(file)file.onchange=async()=>{try{const f=file.files[0];if(!f)return;const startingState=state,request=++importRequest;if(f.size>100000)throw new Error('存档超过大小限制。');const imported=parseSave(await f.text());if(request!==importRequest||startingState!==state){toast('读取期间进度已变化，请重新选择存档。');return;}if(dialog.open){toast('请先关闭当前对话，再导入存档。');return;}modal('导入这个进度？',`<p>${esc(imported.name)} · 第 ${imported.day} 天 · ${money(imported.cash)}</p><p>确认后会替换当前进度。建议先导出备份。</p>`,()=>{state=imported;tab='desk';personFilter='all';memoryFilter='all';newPortraitId=null;newArtworkId=null;save();notice='存档已恢复。';render();},state?'替换并继续':'恢复并继续');}catch(e){toast('导入失败：'+e.message);}finally{file.value='';}};}
function render(){
 if(!state){renderStart();return;}
 app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="wordmark"><img src="assets/mark.svg" alt=""><span>外贸达人养成记<small>TRADE TYCOON</small></span></div><nav aria-label="主导航">${[['desk','工作台'],['people','身边的人'],['company','公司'],['journal','手账']].map(([id,label])=>`<button data-action="tab" data-id="${id}" class="nav-item ${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}><span>${icon(id)}</span>${label}</button>`).join('')}</nav><div class="sidebar-story">${scene()}<strong>从这里，走向世界。</strong><p>一份报价，一次相遇。<br>航线由你定义。</p></div><div class="player-summary"><span class="player-monogram">${esc(state.name.slice(0,1))}</span><div><strong>${esc(state.name)}</strong><small>${state.stage==='employee'?'启航贸易 · 业务员':'向海贸易 · 创始人'}</small></div></div></aside><main class="main"><header class="topbar"><div><span class="eyebrow">${chapter(state)}</span><p><strong>第 ${state.day} 天 · ${weekday(state)}</strong><span class="day-dot">·</span>${state.phase==='day'?'上午，海风刚好':'傍晚，灯光温柔'}</p></div><div class="header-actions"><button class="sound-toggle" data-action="sound" aria-pressed="${soundEnabled()}" aria-label="${soundEnabled()?'关闭':'开启'}轻音效" title="轻音效默认关闭，不播放背景音乐">${soundEnabled()?'♫':'♪'}<span>${soundEnabled()?'音效开':'音效关'}</span></button>${button(state.phase==='day'?(isWeekend(state)?'休息与约会 →':'下班 →'):'回家休息 →',state.phase==='day'?'evening':'rest','','button secondary')}</div></header><div class="stats"><div><small>${state.stage==='employee'?'我的积蓄':'周转资金'}</small><strong>${money(state.cash)}</strong>${state.active?.reserve?`<span>另有 ${money(state.active.reserve)} 垫资在途</span>`:''}</div><div><small>合作口碑</small><strong>${state.rep}<em>点</em></strong></div><div><small>顺利交付</small><strong>${state.completed}<em>单</em></strong></div><div class="state-label"><small>当前身份</small><strong>${state.stage==='employee'?'外贸新人':'独立创业'}</strong></div></div>${saveWarning?`<p class="warning">${esc(saveWarning)}</p>`:''}${notice&&(!state.active||tab!=='desk')?feedback():''}<div class="page-content">${tab==='desk'?storyPanel():''}${({desk,people,company,journal}[tab]||desk)()}</div><footer>向海而生 · 外贸达人养成记 <span>本地自动保存 · v1.0.1</span></footer></main></div>`;
 bindImport();
}
app.addEventListener('click',e=>{
 const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const type=el.dataset.action,id=el.dataset.id;
 if(type==='sound'){const enabled=setSoundEnabled(!soundEnabled());if(enabled&&!playSound('tap')){setSoundEnabled(false);toast('当前浏览器暂时无法播放音效，游戏仍可正常进行。');}try{localStorage.setItem(SOUND_KEY,soundEnabled()?'on':'off');}catch{}render();return;}
 if(type==='gender'){const name=document.querySelector('#player-name').value;startGender=id;renderStart();document.querySelector('#player-name').value=name;return;}
 if(type==='portrait-view'){viewPortrait(id);return;}
 if(type==='person-select'){if(id==='all'||PEOPLE.some(p=>p.id===id&&personUnlocked(state,id))){personFilter=id;tab='people';render();document.querySelector('.people-shortcuts')?.scrollIntoView?.({block:'start',behavior:'instant'});}return;}
 if(type==='tab'){tab=id;notice='';newPortraitId=null;newArtworkId=null;render();window.scrollTo({top:0,behavior:'instant'});return;}
 if(type==='dismiss'){notice='';newPortraitId=null;newArtworkId=null;render();return;}
 if(type==='export'){let raw;try{raw=state?JSON.stringify(state,null,2):localStorage.getItem(KEY);}catch{}if(!raw){toast('没有可导出的存档。');return;}const url=URL.createObjectURL(new Blob([raw],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`外贸达人养成记-第${state?.day||'旧'}天.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('存档已准备下载。');return;}
 if(type==='import'){document.querySelector('#import-file').click();return;}
 if(type==='reset'){modal('重新开始一段故事？','<p>这会替换当前浏览器的进度。若想保留，请先取消并导出存档。</p>',()=>{try{localStorage.removeItem(KEY);}catch{toast('浏览器暂时无法清除存档，当前进度已保留。');return;}importRequest++;state=null;tab='desk';personFilter='all';memoryFilter='all';newPortraitId=null;newArtworkId=null;notice='';saveWarning='';render();},'重新开始',true);return;}
 if(type==='startup'){modal('创立向海贸易',`<p>完成交接，支付启动费用 <strong>¥3,000</strong>，剩余周转资金 <strong>${money(state.cash-3000)}</strong>。</p><p>此后自行垫资并获得全部净利润，不再领取员工日薪。朋友和恋人仍然可以在下班后见面。</p>`,()=>act({type}),'带着准备出发');return;}
 if(type==='story-open'){openStory(id);return;}
 if(type==='story-review'){openStory(id,true);return;}
 if(type==='finale'||type==='finale-review'){showFinale(type==='finale-review');return;}
 if(type==='commit'){const p=PEOPLE.find(p=>p.id===id);modal(`和${p.name}认真谈谈`, '<p>你们已经愿意更认真地走向彼此。是否现在确认一段正式关系？这会使用今晚的相处机会。</p><p>这会停止与其他人的未承诺约会，保留友谊与合作。你之后仍可选择结束关系，不会损失经营资源。</p>',()=>act({type,id}),'把心意说清楚');return;}
 if(type==='chat'){conversation(id);return;}
 if(type==='date'){dateConversation(id);return;}
 if(type==='work-story-open'||type==='work-story-review'){openWorkStory(id,type==='work-story-review');return;}
 if(type==='memory-review'){reviewMemory(id);return;}
 if(type==='memory-art'){viewRelationshipArt(id);return;}
 if(type==='memory-person'){if(id==='all'||PEOPLE.some(p=>p.id===id&&personUnlocked(state,id))){memoryFilter=id;tab='journal';notice='';render();document.querySelector('.memory-archive')?.scrollIntoView?.({block:'start',behavior:'instant'});}return;}
 if(type==='boundary'){const p=PEOPLE.find(p=>p.id===id);modal('把关系说清楚',`<p>告诉${p.name}你希望保持朋友与合作关系。此后不会主动出现恋爱推进，工作收益与信任不受影响。</p>`,()=>act({type,id}),'保持朋友关系');return;}
 if(type==='cancel'){modal('暂缓这笔订单？','<p>当前版本会退回已预留的垫资，不收取消费。已经使用的工作步骤不会返还，今天不再显示这笔询盘。</p>',()=>act({type}),'暂缓订单');return;}
 if(type==='recruit'){const p=PEOPLE.find(p=>p.id===id);if(!p.recruit||state.relations[id].trust<3||state.startupOrders<2){act({type,id});return;}modal(`邀请${p.name}加入`, `<p>${p.promise}</p><p>对方认可目前的岗位与计划，愿意接受邀请。入职安排费用 <strong>¥1,200</strong>，每日工资 <strong>¥80</strong>。不要求恋爱关系。</p>`,()=>act({type,id}),'正式邀请');return;}
 if(type==='ending'){act({type});modal('航线，由你定义',`<div class="ending-stamp">向海贸易<br><small>第一章 · 顺利启航</small></div><p>你完成了 ${state.completed} 笔订单，收获 ${state.rep} 点合作口碑。</p><p>${Object.values(state.relations).some(r=>r.status==='dating')?'有人在工作之外，与你分享晚风。':'把生活留给自己，也是一种完整的选择。'}</p><p>这只是创业的起点。你可以继续经营、相处和建设公司，按公司页的目标抵达完整的事业终章。</p>`,()=>{},'继续我的生活');return;}
 act({type,id});
});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{const incoming=e.newValue?parseSave(e.newValue):null;dismissDialog();importRequest++;state=incoming;personFilter='all';memoryFilter='all';newPortraitId=null;newArtworkId=null;saveWarning='';notice='已同步另一个窗口的最新进度，请重新选择未完成的对话。';render();}catch{toast('另一个窗口的存档无法读取。当前进度保留。');}});
render();
